StripeWebhookController.java<pre><code>@RestController
@RequestMapping("/api/webhook")
public class StripeWebhookController {

    @Value("${stripe.webhook-secret}")
    private String webhookSecret;

    @Autowired
    private WebhookEventHandler eventHandler;

    @PostMapping("/stripe")
    public ResponseEntity&lt;String&gt; handleWebhook(
            @RequestBody String payload,
            @RequestHeader("Stripe-Signature") String sigHeader) {

        Event event;
        try {
            // 验证签名
            event = Webhook.constructEvent(payload, sigHeader, webhookSecret);
        } catch (SignatureVerificationException e) {
            log.error("Webhook signature verification failed", e);
            return ResponseEntity.status(400).body("Invalid signature");
        }

        // 处理事件
        try {
            eventHandler.handle(event);
        } catch (Exception e) {
            log.error("Error handling webhook event: {}", event.getType(), e);
            // 返回 200 避免 Stripe 重试（已记录错误，手动处理）
        }

        return ResponseEntity.ok("Received");
    }
}
